import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"46、【升】 巽下坤上","description":"周易阐真 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"周易阐真 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"zh/classics/chanzhen/047.md","filePath":"zh/classics/chanzhen/047.md"}'),s={name:"zh/classics/chanzhen/047.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：柔以时升，巽而顺，刚中而应，是以大亨，用见大人勿恤，有庆也。南征吉，志行也。</p></blockquote><h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>初六：允升，大吉。</p><p>九二：孚乃利用禴，无咎。</p><p>九三：升虚邑。</p><p>六四：王用亨于岐山，吉，无咎。</p><p>六五：贞吉，升阶。</p><p>上六：冥升，利于不息之贞。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：地中生木，升。君子以顺德，积小以高大。</p><p>升者，增升也。上坤地，下巽木，是地中生木也。木自地中而生，渐次出地，升之象也。</p><p>君子有见于此，知人之不能高大其德者，皆由不知顺其德而悖其德。不顺其德，舍其近而求其远，悬虚不实，永无增升之日。以是顺德，积小以高大焉。积者，高之渐；小者，大之由。顺时顺理，是谓顺德。能顺其德，防微杜渐，戒慎恐惧，小善必为，微恶必去，愈久愈力，工夫不缺，日积日多，自小而渐至于高大；亦如地中生木，始而在地中，渐而出地外，又渐而干立枝盛，又渐而高大成材。高大之材，岂一朝一夕之功哉?一切学人，不肯下实落工夫，方才进步，便想成道，未曾入门，即欲入室。如此存心，是不顺德而顺欲，焉能到得高大之处?卦象坤巽合成，渐进而顺行，所谓深造自得者，不在此乎?</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>用亨，亨作享。冥，音明。</p><p>升者，自卑登高之义。卦德上坤顺，下巽入，徐缓进步，顺时而行，不即不离，渐入真常，故谓升。此谨慎火候之卦，承上姤卦而来。姤者，巽入于健，阳极阴生，邪气日进，正气日退，习染成性，渐入下愚不移之地矣。所以者何?因其阳失其健，阴亦不顺耳。</p><p>金丹大道，未复其阳，先顺其阴，阴若一顺，则人欲不生，正念常存，循序渐进，可以自无而至有，自虚而至实，下学上达，明善复初而无难，故升有元亨之道也。但此元亨之升，乃窃阴阳，夺造化，超凡入圣之事，其中火候细微，工程悠远，非一切妄猜私议，盲修瞎炼者所能行，必须真师口传心授，真知确见，方能一直前行，无阻无挡，是以用升之道，利于见大人也。大人，即完成大道之圣人。盖大人成己成物，一言一语，俱有道理。如风之无物不入，能以开人之智慧；如地之无物不长，能以救人之灾殃。见大人而后用之，则药物得真，火候有准，可以勿恤，向明远行，一步有一步之益，一日有一日之功，自卑登高，由浅及深，终必进于圣贤之域，其吉为何如乎?</p><p>初六，性柔志刚，虚心自下，亲近有道之士，而高明者，未有不允其升，不授其真者。此柔而顺刚之升也。</p><p>九二，刚而有得于中，深明药物火候，以诚而入，以柔而用，渐次下功，如以禴祭神，用诚感通，必升于一无所咎之地矣。此刚而用柔之升也。</p><p>九三，予圣自雄，不知寻师访友，妄猜私议，冒然前进，欲向其前，反落于后，如升于虚邑，何能进于高明之地?此不知求师之升也。</p><p>六四，柔而守正，顺时进步，炼己持心，自卑登高，渐入佳境，如王用享于岐山，未有不升于上者。此吉而无咎之升也。</p><p>六五，虚人心而求道心，虚心即能实腹。所谓一念回机，如同本得，其增益道德，如升阶之易。此柔而虚心之升也。</p><p>上六，愚而自用，执着一己之阴，妄想增升道德，了命了性，升之不息，冥之不息，愈升愈冥，焉能出晦暗而进于高明?若欲升之不冥，必须求师口诀，利于不息之贞，惩忿窒欲，闲邪存诚，愈久愈力，亦可升于明善复初之地。此柔而归正之升也。</p><p>升之为道，以刚道而行柔道也。卦德巽而顺行，外柔内刚，循序渐进，不急不缓，深造自得，未有不升于圣贤之堂奥者。然火候之秘，总要真师口传心授。《彖》曰：“用见大人，勿恤，南征吉。”可以知矣。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
